contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take an amount to deposit; then we call deposit and then withdrawAll.
    // We assert the general invariant: if withdrawAll did not revert, then
    // (1) the caller's observable credit (via deposit/withdraw effects) is zero,
    // and (2) the contract's balance did not increase as a result of withdraw (it decreased by at most the deposited amount).
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // record contract balance before any interactions
        uint beforeBal = address(c).balance;

        // perform deposit of `amount`
        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;

        // record contract balance after deposit
        uint afterDepositBal = address(c).balance;

        // now try withdrawAll and capture whether it reverted
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // record contract balance after withdraw attempt
        uint afterWithdrawBal = address(c).balance;

        // read credit by attempting to deposit zero and then withdrawAll to observe behavior is not allowed here
        // But C has no public getter for credit, so we observe via effects: if a subsequent withdrawAll succeeds with zero change, credit was zero.
        // To avoid making extra state-changing calls, we instead assert using available observations: when withdrawAll succeeded,
        // the contract balance cannot have increased when compared to afterDepositBal, and the balance decrease is at most amount deposited.
        // Formulate: if not reverted then afterWithdrawBal <= afterDepositBal and (afterDepositBal - afterWithdrawBal) <= amount

        assert(reverted || (afterWithdrawBal <= afterDepositBal && (afterDepositBal - afterWithdrawBal) <= amount));
    }

    receive() external payable { }
}

